package com.github.alfu32.sketch.tools

import java.io.ByteArrayInputStream
import java.util.Base64
import java.util.zip.GZIPInputStream

object EmbeddedVectorGlyphCatalog {
    private const val COMPRESSED_BASE64 =
        ""

    fun load(): VectorGlyphCatalog {
        return try {
            val compressed = Base64.getDecoder().decode(COMPRESSED_BASE64)
            val json = GZIPInputStream(ByteArrayInputStream(compressed)).bufferedReader(Charsets.UTF_8).use { it.readText() }
            VectorGlyphCatalog.fromCompactGlyphJson(json, "embedded:alphabet") ?: VectorGlyphCatalog.empty("embedded:alphabet")
        } catch (_: Throwable) {
            VectorGlyphCatalog.empty("embedded:alphabet")
        }
    }
}
